@module midiBlob  src=midiBlob.lua  loc=311  sha=3137af5  mode=namespace  self=midiBlob

# Invariants & contracts
  @invariant  idx is the 0-based REAPER per-type index; note idx counts note-ons, text idx skips CCBZ  @ 13
  @reaper  blob = repeat(i4 offset, B flags, s4 msg) + trailing 12-byte all-notes-off tail (excluded)  @ 14
  @reaper  flags bit1=muted; bits4-6=cc shape; status byte classifies; CCBZ rides FF-0F after its cc  @ 15
  @invariant  a note/cc slot stays under 5e4: seq2 = slot*2 shares the key's 1e5 digit band with rank  @ 143
  @invariant  parse(render(buildWire(x)))==x; coincident events may reorder, per-type lists intact  @ 144
  @invariant  note onsets unique per (ppq,chan,pitch); collision is upstream bug, warn+write  @ 145
  @reaper  matches MIDI_SetAllEvts format; tail at max(endPpq, last-event ppq) (default: last event)  @ 146

# Shapes
  @shape  parse(blob) -> notes, ccs, texts, passthrough  @ 9
  @shape  note = { idx, evType='note', ppq, endppq, chan(1..16), pitch, vel, [muted] }  @ 10
  @shape  cc = { idx, ppq, evType, chan(1..16), [cc|pitch], [val|vel], shape, [tension], [muted] }  @ 11
  @shape  text = { idx, ppq, eventtype, msg }  -- 15=notation, -1=sysex; CCBZ tension folds onto its cc  @ 12
  @shape  wire = { keys = { [i] = ppq*1e6 + rank*1e5 + seq2 }, chunks = { [i] = packed bytes for keys[i] } }  -- keys ascending and dense 1..n, chunks index-parallel  @ 140
  @shape  buildWire(notes, ccs, texts, passthrough) -> wire   -- notes/ccs keyed by slot (a dense array is the case slot==index)  @ 141
  @shape  render(wire, endPpq?) -> blob   -- concat plus the EOT tail; endPpq places the tail  @ 142

